document.getElementById('hdr').innerHTML='<div class="wrap"><a href="/" style="height:30px;display:block" aria-label="Chag Solutions"><span class="lg" style="display:block;height:30px;width:78px">'+LOGO+'</span></a><nav>'+pages.map(p=>'<a href="'+p[0]+'"'+(p[0]===cur?' class="on"':'')+'>'+p[1]+'</a>').join('')+'</nav></div>';
